const albums = [{"id":"velvet-dominion","artist":"越黒リタ","title":"Velvet Dominion","albumNumber":1,"release":"2025.12.13","story":["闇は光を失った場所ではなく、美しさと誇りが静かに息づく領域として広がっている。薔薇は罪を飾り、祈りは滅びへ姿を変え、痛みさえも気高さを映し出す装飾となる。揺らぐことのない意志だけが、この静寂に満ちた世界を支えている。","孤独を抱きしめ、救いさえ選ばずに歩み続ける姿は、誰かに与えられた運命ではなく、自ら選び取った生き方そのものである。美しく在ることを貫いた先で、夜は何も裁かず、ただ静かにその名を受け入れていく。"],"tracks":[{"title":"Queen of the Velvet Night"},{"title":"Nocturne Marionette"},{"title":"Ðesire"},{"title":"Sanctus Ruina"},{"title":"Venomous Rose"},{"title":"Crimson Banquet"}],"art":"covers/velvet-dominion.png","accent":"crimson","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ベルベット・ドミニオン"},{"id":"lunar-eclat","artist":"越黒リタ","title":"Lunar Éclat","albumNumber":2,"release":"2025.12.13","story":["鏡や仮面の向こうに潜むもう一人の自分は、偽りではなく、隠し続けてきた欲望や痛みの輪郭として現れる。美しさは誰かに認められるための姿ではなく、嫉妬も狂気も傷も抱えたまま、自らを受け入れるための光へと変わっていく。","甘い誘惑に身を委ね、名前や記憶さえほどけていく夜の中で、真実と虚構の境界は静かに失われる。最後に残るのが素顔なのか、選び取った幻なのか――その答えは、割れた鏡の奥で今も微笑んでいる。"],"tracks":[{"title":"Mirror Elegy"},{"title":"Alice in the Abyss"},{"title":"Shadowed Apple"},{"title":"Noir Élégance"},{"title":"Noble Masquerade"},{"title":"Scarlet Nepenthe"}],"art":"covers/lunar-eclat.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ルナー・エクラ"},{"id":"luminous-ruin","artist":"越黒リタ","title":"Luminous Ruin","albumNumber":3,"release":"2025.12.13","story":["美しさは飾りによって生まれるのではなく、壊れながらもなお失われなかった想いの中に宿っている。偽りも孤独も祈りも、この世界では滅びを恐れるためではなく、自らを受け入れるための欠片として静かに重ねられていく。","名前や存在の意味さえ曖昧になる夜の果てで、それでも胸に残る鼓動だけは消えることがない。壊れたものは終わりではなく、新たな美しさの始まりなのかもしれない。──夜だけが、その静かな輝きを見つめている。"],"tracks":[{"title":"Ornament of Ruin"},{"title":"R"},{"title":"Mechanical Prayer"},{"title":"Dream Eater"},{"title":"Veiled Eden"},{"title":"Nameless Alice"}],"art":"covers/luminous-ruin.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ルミナス・ルイン"},{"id":"oboromiyabi","artist":"越黒リタ","title":"朧雅","albumNumber":4,"release":"2026.01.01","story":["月明かりに照らされた影は、決して触れることのできない美しさを宿している。幻も妖も散りゆく花も、その儚さゆえに心を惹きつけ、静かな憧れとなって胸の奥へ染み込んでいく。届かない距離は悲しみではなく、美を永遠に保つための余白として息づいている。","闇へ近づくほど輪郭は曖昧になり、それでも心だけは確かに惹かれていく。名を知らず、触れることも叶わない存在だからこそ、その想いは色褪せることなく夜に寄り添い続ける。──静寂だけが、その雅を知っている。"],"tracks":[{"title":"幻火"},{"title":"葬桜"},{"title":"夜纏"},{"title":"妖紅"},{"title":"墨染"},{"title":"影寄"}],"art":"covers/oboromiyabi.jpg","accent":"amber","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"オボロミヤビ"},{"id":"sugar-deception","artist":"越黒リタ","title":"$ugar Ðeception","albumNumber":5,"release":"2026.01.11","story":["甘い微笑みの裏で交わされる視線は、憧れや愛情だけでは満たされない渇きを静かに映し出している。与える者と求める者、その境界は曖昧に溶け合い、互いの存在を確かめ合うたび、優しさは少しずつ甘い束縛へと姿を変えていく。","誰かの理想として生きることも、誰かを理想に変えてしまうことも、同じ孤独から生まれた願いなのかもしれない。拍手が止んだあとも消えないものは、愛でも支配でもなく、居場所を求め続けた心の痕跡だけである。"],"tracks":[{"title":"ファンサ×罠"},{"title":"ポイズン★アイドル"},{"title":"†冥土カフェ†"},{"title":"月灯シンデレラ♪"},{"title":"依存レッテル◆"},{"title":"わたしのつくりかた"}],"art":"covers/sugar-deception.jpg","accent":"crimson","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"シュガー・ディセプション"},{"id":"fractured-order","artist":"越黒リタ","title":"Fractured Order","albumNumber":6,"release":"2026.02.14","story":["秩序が崩れる音は、終わりを告げる響きではなく、新たな輪郭を刻み始める鼓動となる。迷いも狂気も痛みも、この世界では拒むべき傷ではなく、自らの存在を確かめるための証として積み重ねられていく。壊れることは喪失ではなく、偽りを脱ぎ捨てるための静かな選択なのである。","砕け散った欠片は二度と元には戻らない。それでも残された破片だけが、その者だけの真実を映し出している。崩壊の果てに待つものは虚無ではなく、自ら選び取った自由の姿。──静かに崩れゆくその瞬間こそ、美は最も鮮やかに息づいている。"],"tracks":[{"title":"Broken Awakening"},{"title":"Abyssal Dance"},{"title":"Sweet Venom"},{"title":"Bloodstained Chain"},{"title":"Black Labyrinth"},{"title":"The Shape of Collapse"}],"art":"covers/fractured-order.jpg","accent":"crimson","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"フラクチャード・オーダー"},{"id":"midnight-sirens","artist":"越黒リタ","title":"Midnight Sirens","albumNumber":7,"release":"2026.02.22","story":["夜の奥には、光の世界から離れ、それぞれの美しさと罪を抱いて生きる者たちがいる。黒い翼、魂を奪う歌声、森に宿る誇り、甘い罪を運ぶ妖精、囁きで心を惑わせる夢魔。その姿は異なっていても、誰もが救いではなく、抗いがたい魅惑によって見る者を闇へと招いていく。","彼女たちが差し出すものは祝福なのか、それとも逃れられない契約なのか。光と影の境界で最後に残るのは、誘惑した者の答えではなく、誘われた者自身が下した選択だけである。──真夜中の歌声は、今も静かにその心を呼んでいる。"],"tracks":[{"title":"The Fallen"},{"title":"Darkness Diva"},{"title":"Pride of Night"},{"title":"Sweet Sin Fairy"},{"title":"Whisper of Temptation"},{"title":"Weight of Choice"}],"art":"covers/midnight-sirens.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ミッドナイト・サイレンズ"},{"id":"enmusubi","artist":"越黒リタ","title":"艶結ビ","albumNumber":8,"release":"2026.03.14","story":["甘い囁きは心を癒やすためではなく、静かに距離を奪い、目には映らない絆を結んでいく。欲望、執着、拒絶、支配――交わされる感情は決して単純な愛ではなく、触れることなく心を絡め取る危うい均衡として描かれている。自由と服従の境界は、気づかないほど穏やかに溶け合っていく。","結ばれているのは身体ではなく、逃れようとするほど深く惹かれてしまう心そのもの。誰が縛り、誰が囚われているのか、その答えは最後まで曖昧なまま残される。──見えない結び目だけが、静かに二人を繋ぎ続けている。"],"tracks":[{"title":"官能堪能"},{"title":"冷たい楽園。"},{"title":"都合のいい夢"},{"title":"甘い拘束"},{"title":"見えない首輪"},{"title":"拒絶の距離"}],"art":"covers/enmusubi.jpg","accent":"crimson","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"エンムスビ"},{"id":"nocturnal-rite","artist":"越黒リタ","title":"Nocturnal Rite","albumNumber":9,"release":"2026.03.20","story":["夜は終わりを告げる時間ではなく、自らの存在を受け入れるための静かな儀式となる。黒衣を纏い、杯を掲げ、翼を選び、蛇の囁きに耳を澄ませ、棺と王冠を受け継ぎ、祈りさえも自らの手で結び直す。その一つひとつは、誰かに与えられた運命ではなく、自分自身を形づくるための通過儀礼として描かれている。","ここで捧げられるのは信仰ではなく、揺るぎない意志である。終わりを恐れず、孤独を拒まず、夜を選び続ける者だけが辿り着く静かな戴冠。その儀式は誰にも見えないまま、今も深い夜の中で続いている。──闇は隠れる場所ではなく、己を証明するための聖域となる。"],"tracks":[{"title":"闇を着る"},{"title":"骸の祝杯"},{"title":"夜を選ぶ蝙蝠"},{"title":"蛇が眠る場所"},{"title":"棺と王冠"},{"title":"背徳のロザリオ"}],"art":"covers/nocturnal-rite.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ノクターナル・ライト"},{"id":"nachtgarten","artist":"越黒リタ","title":"Nachtgarten","albumNumber":10,"release":"2026.04.16","story":["夜の庭園には、誰にも触れられることなく静かに息づく、美しくも危うい命たちが咲いている。砕けやすい果実、深淵に根を張る花、月夜を舞う蝶、不可能を象徴する青薔薇、甘く誘う罠、そして記憶に残り続ける香り。それぞれは異なる姿を持ちながらも、儚さと危険さを同時に宿し、見る者を静かな夜の奥へと誘っていく。","この庭園にあるものは、所有するための美ではなく、ただ出会い、見つめるための美しさである。触れようとした瞬間に形を変え、離れたあとも心に残り続けるその気配は、夜だけが育てる命の証なのかもしれない。──静寂に包まれた庭園では、今も誰にも知られず花が咲き続けている。"],"tracks":[{"title":"ガラスの果実"},{"title":"深淵に咲く花"},{"title":"夜に愛された蝶"},{"title":"青薔薇の花弁"},{"title":"誘いの縁"},{"title":"夜の残香"}],"art":"covers/nachtgarten.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ナハトガルテン"},{"id":"aeternitas","artist":"越黒リタ","title":"Aeternitas","albumNumber":11,"release":"2026.04.25","story":["現実と悪夢の境界が静かに崩れ、名前も時間も、ひとつずつ輪郭を失っていく。沈黙と深い意識の底では、自分と世界を隔てていたものさえ溶け、祈りや孤独も、ただ存在するための静かな広がりへと姿を変えていく。","永遠とは、終わらない時を生きることではなく、始まりも終わりも超えて在り続けることなのかもしれない。救いを待たず、自ら選んだ夜の果てで、その存在は静寂そのものとなる。──闇だけが、消えない輪郭を抱いている。"],"tracks":[{"title":"悪夢未満"},{"title":"沈黙が続く限り"},{"title":"境界融解"},{"title":"意識の海"},{"title":"在り続ける場所"},{"title":"果てのない夜へ"}],"art":"covers/aeternitas.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"エテルニタス"},{"id":"vitia","artist":"越黒リタ","title":"ViTiA","albumNumber":12,"release":"2026.05.16","story":["人の心には、言葉では説明しきれない衝動や感情が静かに潜んでいる。孤高、拒絶、衝動、執着、過剰、停滞――それらは善悪では測れず、ときに誰もが胸の奥で抱え続ける静かな本能として姿を現す。それぞれに与えられた名は、恐れるためではなく、人間の内側を映し出す象徴として響いている。","この作品が描くのは、罪へ堕ちる物語ではない。誰にも見せることのない感情と向き合い、その存在を否定せず受け入れていく過程である。光だけでは語れない心の深層は、名前を得た瞬間から静かに輪郭を持ち始める。──その名を知った夜、人は初めて自分自身と向き合うのである。"],"tracks":[{"title":"Lucifer Pride"},{"title":"Cold Satan"},{"title":"Asmodeus Pulse"},{"title":"Mammon Weight"},{"title":"Beelzebub Overdose"},{"title":"Belphegor Stasis"}],"art":"covers/vitia.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ヴィティア"},{"id":"silent-sovereign","artist":"越黒リタ","title":"Silent Sovereign","albumNumber":13,"release":"2026.05.30","story":["支配は、大きな声や力によって始まるものではない。最初の選択、小さな信頼、安心という名の油断、揃えられた秩序――静かに積み重ねられた意識の流れは、やがて誰も気づかないまま世界の向きを変えていく。そこでは勝敗さえも結果ではなく、盤上に立つ者たちの心理そのものが駆け引きとなる。","この作品が描く王とは、玉座に座る支配者ではなく、沈黙の中で空気を支配する存在である。動かずとも流れを変え、語らずとも意志を示し、最後には盤面の外側からすべてを見つめ続ける。──静かな王権とは、誰かを従わせることではなく、世界そのものの呼吸を支配することで完成する。"],"tracks":[{"title":"FIRST SIN"},{"title":"False Embrace"},{"title":"Silent Majority"},{"title":"Cold Brilliance"},{"title":"Quiet Authority"},{"title":"Out of the Deck"}],"art":"covers/silent-sovereign.jpg","accent":"amber","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"サイレント・ソヴリン"},{"id":"black-coronation","artist":"越黒リタ","title":"Black Coronation","albumNumber":14,"release":"2026.06.06","story":["王冠は誰かに授けられる褒賞ではなく、自ら選び取った意志の証として静かに掲げられる。完璧な聖域を壊し、均衡へひびを刻み、世界の継ぎ目を編み直しながら、既存の救済や正しさを越えて歩み続ける。その歩みは支配を望むためではなく、自分だけの存在理由を証明するための戴冠へと繋がっていく。","ここで描かれる王とは、人々の上に立つ支配者ではない。何にも跪かず、何者の名も借りず、それでも揺るがない意志を抱き続ける存在である。祝福の鐘が鳴らなくても、その王冠は確かに夜の頂で輝いている。──黒き戴冠とは、誰にも奪われない誇りが完成した瞬間なのである。"],"tracks":[{"title":"存在圧"},{"title":"硝子の聖域"},{"title":"均衡のひび"},{"title":"創造の裏側"},{"title":"神を拒む玉座"},{"title":"黒の戴冠"}],"art":"covers/black-coronation.jpg","accent":"crimson","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ブラック・コロネーション"},{"id":"cathedral-of-masks","artist":"越黒リタ","title":"Cathedral of Masks","albumNumber":15,"release":"2026.06.20","story":["大聖堂に並ぶ仮面は、素顔を隠すためではなく、人の心を静かに導くために存在している。微笑み、慈悲、純白、享楽、沈黙、そして空白――それぞれは異なる表情を持ちながらも、拒絶や暴力ではなく、優しさや静寂によって少しずつ意志や距離を変えていく。支配は決して強制ではなく、自ら選んだと思わせるほど穏やかに完成していく。","仮面の奥にあるものは、善悪で語れる本心ではない。幾重にも重ねられた感情や願い、そして誰にも見せることのない静かな深層である。最後に残る空白は喪失ではなく、すべてを受け入れてなお揺るがない中心。その大聖堂では今日も、名もなき仮面たちが静かに来訪者を見つめ続けている。"],"tracks":[{"title":"微笑のヴェール"},{"title":"恩寵のアリア"},{"title":"純白のストラテジー"},{"title":"退廃のセレナーデ"},{"title":"沈黙のグラヴィティ"},{"title":"ホロウ・コア"}],"art":"covers/cathedral-of-masks.jpg","accent":"amber","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"カテドラル・オブ・マスクス"},{"id":"crown-of-jewel","artist":"越黒リタ","title":"Crown of Jewel","albumNumber":16,"release":"2026.07.03","story":["六つの宝石は、装飾として輝くためではなく、それぞれが異なる意志や感情を宿す象徴として静かに存在している。砕けない強さ、胸に秘めた情熱、深淵の静寂、真実を見抜く眼差し、幻想へ誘う夢、そしてすべてを包み込む闇。それぞれの輝きは互いに競うことなく、人の心が持つ多彩な在り方を映し出している。","磨かれるたびに増すのは美しさだけではない。傷も孤独も沈黙も、そのすべてが輝きの奥深くへと刻まれ、唯一無二の色彩を形づくっていく。最後に残る黒は光を失った色ではなく、あらゆる輝きを受け入れた静かな完成形。──王冠を飾る宝石は、誰かに選ばれた証ではなく、自ら生き抜いた軌跡そのものなのである。"],"tracks":[{"title":"Diamond Edge"},{"title":"Ruby Heart"},{"title":"Abyss Sapphire"},{"title":"Emerald Eye"},{"title":"Amethyst Dream"},{"title":"Onyx Void"}],"art":"covers/crown-of-jewel.jpg","accent":"purple","youtubeId":"Pgr0gN0VOUI","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"クラウン・オブ・ジュエル"},{"id":"lune-noire","artist":"越黒リタ","title":"Lune Noire","albumNumber":17,"release":"2026.07.17","story":["夜空に浮かぶ月は、ただ光を映す天体ではなく、心の奥で移ろい続ける感情の象徴として静かに巡っている。満たされない憧れ、光と影の揺らぎ、陶酔へと至る歓び、わずかな違和感に宿る美しさ、抑えきれない衝動、そしてすべてが過ぎ去ったあとの静かな余韻。それぞれの月相は、ひとつの夜が辿る心の軌跡を映し出している。","月は決して同じ姿を留めない。それでも欠けることも満ちることも、そのすべてが夜を完成させるために必要な輪郭である。消えたはずの感情も、残響となって静かに胸へ降り積もり、やがて次の夜を呼び覚ます。──黒き月は終わりではなく、繰り返し巡る心の満ち欠けを、永遠に照らし続けている。"],"tracks":[{"title":"Crescent Desire"},{"title":"Dual Eclipse"},{"title":"Lunar Ecstasy"},{"title":"Azure Temptation"},{"title":"Crimson Instinct"},{"title":"Silent Absence"}],"art":"covers/lune-noire.jpg","accent":"blue","youtubeId":"FBlF8HkpsKI","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"リュヌ・ノワール"},{"id":"hollow-salvation","artist":"CROVEIL","title":"Hollow Salvation","release":"2026.04.16","order":18,"story":["紅い渇望は静かに夜を染め、罪も孤独も、美しさへ変わるための証として刻まれていく。仮面の舞踏、支配する静寂、契約に縛られた人形、黒き王冠、そして毒を宿した花。それぞれの情景は、滅びへ向かう絶望ではなく、闇を受け入れた者だけが辿り着く退廃の美学として描かれている。","この作品が求める救済は、光へ還ることではない。傷も罪も抱いたまま、自ら選んだ夜を生き抜くことである。終焉さえ静かな祝福へ変わる世界で、最後まで消えなかった渇望だけが存在を証明していく。──その漆黒の旋律は、CROVEILという物語の幕開けを告げる最初の鐘となる。"],"tracks":[{"title":"Desire"},{"title":"Nightfall Authority"},{"title":"Nocturne Masquerade"},{"title":"Obsidian Puppet"},{"title":"Crown of Sin"},{"title":"Venom Bloom"}],"art":"covers/hollow-salvation.jpg","accent":"purple","youtubeId":"LFa_UwzIyZ0","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ホロウ・サルヴェーション"},{"id":"crimson-covenant","artist":"CROVEIL","title":"Crimson Covenant","release":"2026.05.21","order":19,"story":["紅き契約は、一瞬の誓いではなく、夜の奥深くへ刻まれた揺るぎない選択として結ばれていく。甘く歪んだ幻想、壊れた楽園、虚栄に揺れる心、絶えず呼び続ける声、存在を刻む証、そして静かな忘却――そのすべては、光へ戻るためではなく、闇と共に生きる覚悟を形づくるための儀式として描かれている。","ここで交わされる契約は、誰かに強いられたものではない。痛みも孤独も、美しささえ抱きしめ、自ら選び取った運命そのものである。記憶が薄れ、名前さえ霧へ溶けていっても、胸に刻まれた契りだけは決して消えない。──紅き契約は、終焉ではなく、永遠に続く夜への静かな誓約なのである。"],"tracks":[{"title":"Black Covenant"},{"title":"Corrupted Wonderland"},{"title":"Vanity Paradox"},{"title":"Still Calling"},{"title":"Scarlet Proof"},{"title":"Crimson Oblivion"}],"art":"covers/crimson-covenant.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"クリムゾン・カヴェナント"},{"id":"trace-of-perfume","artist":"越黒リタ","title":"Trace of Perfume","albumNumber":18,"release":"2026.08.08","order":20,"story":["香りは目に映ることなく、人の記憶や感情だけに静かに触れていく。かすかな気配から始まり、鼓動、残響、微熱、衝動へと少しずつ深まり、最後には姿を失ってもなお消えない余香だけが残される。その変化は強く奪うのではなく、気づかないほど穏やかに心の奥へ染み込み、忘れられない記憶となって積み重なっていく。","香りは触れることも、留めることもできない。それでも一度心へ刻まれた余韻は、時間が過ぎても静かに息づき続ける。見えないからこそ美しく、消えゆくからこそ深く残る。その儚い軌跡は、出会いよりも記憶を描く芸術として、今も夜の空気に溶け込んでいる。"],"tracks":[{"title":"シトラスの気配"},{"title":"フローラルの鼓動"},{"title":"オリエンタルの残響"},{"title":"ジャスミンの微熱"},{"title":"ムスクの衝動"},{"title":"アンバーの余香"}],"art":"covers/trace-of-perfume.jpg","accent":"rose","youtubeId":"PAS8hutHTys","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"トレース・オブ・パフューム"},{"id":"fatal-allure","artist":"越黒リタ","title":"Fatal Allure","albumNumber":19,"release":"2026.08.27","order":21,"story":["白い花は、純粋さではなく、静かに心を蝕む誘惑の象徴として咲き誇る。甘い香りに導かれた想いは、理性と欲望の境界を少しずつ溶かし、美しさの名のもとに新たな自分へと姿を変えていく。","抗うことさえ心地よく、堕ちていくほど景色は鮮やかに色づいていく。選び取ったその一歩が救いなのか破滅なのか、その答えを知る者は、夜だけである。"],"tracks":[{"title":"白に触れた瞬間"},{"title":"輪郭を侵すもの"},{"title":"甘美なる依存"},{"title":"飽和する衝動"},{"title":"断裂する理性"},{"title":"残効に溺れる"}],"art":"covers/fatal-allure.jpg","accent":"rose","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"フェイタル・アリュール"},{"id":"dissonance-cry","artist":"CROVEIL","title":"Dissonance Cry","release":"2026.07.31","order":22,"story":["与えられた輪郭の中で目覚めた存在は、自らの衝動が誰のものなのかを問い始める。装飾によって形を保ち、歪んだ記憶と終わらない悪夢を巡るうちに、正しさも秩序も次第に意味を失っていく。崩壊、虚構、狂気――それらは排除すべき欠陥ではなく、自分がここに在ることを証明するための一部へと変わっていく。","やがて奈落の果てで選ぶのは、元の姿へ戻ることではない。壊れたまま進み、痛みも矛盾も抱き締め、自らの意志で新たな輪郭を刻むこと。完成とは整うことではなく、歪みさえ自分のものとして選び取ること。──壊れたからこそ生まれる美がある。その不協和音は、やがて新たな自分を呼び覚ます声となる。"],"tracks":["Mechanical Requiem","Artificial Bloom","Dissonance Loop","Pulse of Ruin","Abyssal Wonderland","R'"],"art":"covers/dissonance-cry.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ディソナンス・クライ"},{"id":"higan-zankyo","artist":"CROVEIL","title":"彼岸残響","release":"2026.07.31","order":23,"story":["名もなき影に惹かれ、触れることのできない気配を追うほどに、心の奥へ沈んでいた記憶と痛みが浮かび上がっていく。影、常闇の華、狐火、朧月――夜に現れるものたちは彼女を惑わせる幻であると同時に、自らの内側に潜む闇を映し出す鏡でもあった。","やがて辿り着いた彼岸で、紅い花は静かに散ってゆく。失ったものを忘れるためではなく、その痛みさえ己の一部として抱き、手放すために。消えゆくものほど鮮やかに残り、終わりの先にも残響は響き続ける。──これは、名もなき影を追った魂が、自らの闇を受け入れ、彼岸に一輪の花を残すまでの物語。"],"tracks":["影滲ノ灯","影間","常闇ノ華","狐火誘","朧月残影","彼岸ノ残華"],"art":"covers/higan-zankyo.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ヒガンザンキョウ"},{"id":"fallen-sanctuary","artist":"CROVEIL","title":"Fallen Sanctuary","release":"2026.08.22","order":24,"story":["祝福と呼ばれたものは、いつしか逃れられない鎖へと姿を変える。胸元に残された証、甘く意識を侵す夢、夜へ誘う囁き、救済のように響く黒い旋律――光を求めるほど深く沈み、信じていた楽園の輪郭は少しずつ崩れていく。そこで見つけたのは、誰かに与えられる赦しではなく、傷も孤独も自らの一部として受け入れる強さだった。","やがて偽りの救済を捨て、黒き森の最奥から翼を広げる。神にも運命にも跪かず、失ったものさえ力へ変え、自ら選んだ深淵へと堕ちていく。楽園が背後で崩れ去っても、もう振り返ることはない。──聖域とは光に守られた場所ではない。すべてを失ったあと、それでも己として立ち続けられる場所なのだから。"],"tracks":["Relic","Sweet Delusion","Nocturnal Kiss","Black Resonance","Deep Forest","Edenfall"],"art":"covers/fallen-sanctuary.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"フォールン・サンクチュアリ"},{"id":"elegy-of-night","artist":"越黒リタ","title":"Elegy of Night","albumNumber":20,"release":"2026.09.12","order":25,"story":["終わったはずの記憶は、静寂の中で残響となって蘇る。消えた声、失った温度、届かなかった祈り――忘れようとするほど鮮明になるそれらを抱え、月影に誘われるまま夜を彷徨っていく。白い祈りは赦しを求め、黒薔薇は孤独を包み、胸に残された微かな熱だけが、まだ消えていない想いを静かに照らし続ける。","やがて夜は薄明を迎え、すべてを朝の光へと溶かしていく。それでも、失ったものを完全に忘れることはできない。別れとは記憶を消すことではなく、消えない痛みを抱いたまま、それでも夜を見送ること。──夜が終わっても、その声は消えない。最後に残った余韻だけが、静かな哀歌となって胸の奥で響き続ける。"],"tracks":["消えない残響","月影に誘われて","白い祈り","黒薔薇の静寂","夜を裂く微熱","薄明に消える"],"art":"covers/elegy-of-night.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"エレジー・オブ・ナイト"},{"id":"danse-macabre","artist":"越黒リタ","title":"Danse Macabre","albumNumber":21,"release":"2026.09.26","order":26,"story":["月光と燭台に照らされた舞踏会で、仮面を纏った者たちは終わりを知りながら踊り続ける。白薔薇の香り、交わされる口づけ、絡み合う旋律は理性を溶かし、優雅な祝祭を次第に甘美な狂乱へと染めていく。美しさと欲望、陶酔と破滅の境界が失われるほど、誰もその輪舞から逃れることはできなくなっていく。","やがて歓声は消え、棺に捧げるララバイだけが静かな広間に残される。夜が明ければ、砕けた鏡、色褪せた花弁、冷え切った玉座と、かつての祝祭の残響だけがそこにある。永遠に続くように思えた舞踏にも、必ず最後の一音は訪れる。──死がすべてを奪うその瞬間まで、美しく踊り続ける。それこそが、この夜に許された最後の祝祭。"],"tracks":["月下の舞踏会","仮面越しのくちづけ","白薔薇の円舞曲","血染めの祝祭","棺のララバイ","終焉の輪舞曲"],"art":"covers/danse-macabre.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ダンス・マカブル"},{"id":"rosarium-noir","artist":"越黒リタ","title":"Rosarium Noir","albumNumber":22,"release":"2026.10.10","order":27,"story":["深紅の薔薇とネオンが夜を染め、聖歌と重低音が交錯する祝祭が始まる。加速する鼓動、甘く痺れる欲望、硝子の楽園――眩い光に魅せられるほど理性はほどけ、夜は次第に現実と幻想の境界を失っていく。しかし華やかな熱狂の裏側には、砕けた祈り、隠された傷、そして微笑みの奥に閉じ込められた孤独が静かに息づいている。","やがて狂騒は遠ざかり、黒いフリルの人形が踊り続ける夜にも薄明が訪れる。残されるのは、散った花弁と消えかけた灯火、そして胸から離れない最後の夜想曲。美しいものほど永遠には留まれない。それでも、その一瞬の輝きは消えることなく心に刻まれる。──薔薇は夜に咲き、夜とともに散る。けれど深紅に染まった残響だけは、朝が来ても決して色褪せない。"],"tracks":["Rose Riot","Velvet Voltage","Glass Eden","Veil Rosary","Midnight Doll","Scarlet Nocturne"],"art":"covers/rosarium-noir.jpg","accent":"rose","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ロザリウム・ノワール"},{"id":"marionette-garden","artist":"越黒リタ","title":"Marionette Garden","albumNumber":23,"release":"2026.10.24","order":28,"story":["月明かりに閉ざされた庭園で、糸に繋がれた人形たちは壊れかけた微笑みを浮かべながら踊り続ける。黒いレース、砕けたティアラ、月霧に霞む温室、救いを求める聖堂――美しく飾られた世界の奥には、逃れられない孤独と痛みが隠されている。それでも人形たちは祈り、歌い、切れかけた糸の先で自らの意志を探し続ける。","やがて最後の夜、傷も砕けた記憶も消すのではなく、自分自身の一部として抱きしめられることに気づく。完璧な姿でなくても、誰かに動かされなくても、夢を見ることはできる。蒼い月に見守られながら最後の人形は、自らの足で崩れかけた楽園の先へ歩き始める。──糸が切れても、夢は終わらない。壊れた人形たちは今夜、自分の意志で最後の一歩を踏み出す。"],"tracks":["Marionette Cry","Lace Syndrome","Broken Tiara","Moonveil Garden","Puppet Religion","Last Marionette"],"art":"covers/marionette-garden.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"マリオネット・ガーデン"},{"id":"beautiful-nightmare","artist":"越黒リタ","title":"Beautiful Nightmare","albumNumber":24,"release":"","order":29,"story":["砕けた月と無数の扉が、忘れられた名前を悪夢へ誘う。","目覚めたくないほど美しい夜を巡る、六つの幻影。"],"tracks":["Phantom Parade","Silent Promise","Forgotten Name","Garden of Oblivion","Eternal Moon","Beautiful Lie"],"art":"covers/beautiful-nightmare.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ビューティフル・ナイトメア"},{"id":"persona","artist":"越黒リタ","title":"PERSONA","albumNumber":25,"release":"","order":30,"story":["五つの個性が紫の聖堂へ集い、ひとつの音像として目を覚ます。","王座、残響、衝動、影、そして黒翼を刻む六つの肖像。"],"tracks":["Crimson Throne","Twilight Resonance","Scarlet Ignition…","Silent Shadow","Butterfly Tempest","黒翼ノ夜明ケ。"],"art":"covers/persona.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ペルソナ"},{"id":"vanishing-reverie","artist":"越黒リタ","title":"Vanishing Reverie","albumNumber":26,"release":"","order":31,"story":["薄明と星夜の境界で、失われた夢が静かにほどけてゆく。","枯れた湖と忘れられた楽園を辿る、消えゆく世界への六つの追憶。"],"tracks":["夢の抜け殻","沈黙の森","枯れた湖","忘れられた楽園","黄昏に還るように","消えゆく星"],"art":"covers/vanishing-reverie.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ヴァニシング・レヴェリー"},{"id":"yugatou","artist":"CROVEIL","title":"誘蛾灯","release":"","order":32,"story":["月下の灯へ引き寄せられた羽が、甘い毒を纏って夜を舞う。","快楽と飢え、蜜と檻の間で微睡む六つの黒い衝動。"],"tracks":["月下毒","快楽飢餓","蜜の檻","宵待ち","蝶毒","微睡み"],"art":"covers/yugatou.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"ユウガトウ"},{"id":"funeral-bloom","artist":"CROVEIL","title":"Funeral Bloom","albumNumber":7,"release":"","order":33,"story":[],"tracks":["夜を翔ける","黒のままで","蛇は微笑む","深紅の聖杯","神なきロザリオ","棺に眠る君へ"],"art":"covers/funeral-bloom.jpg","accent":"purple","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"フューネラル・ブルーム"},{"id":"celestial-diamond","artist":"越黒リタ","title":"Celestial Diamond","albumNumber":27,"release":"","order":34,"story":[],"tracks":["白銀のシリウス","雪原のプロキオン","双影のミラージュ","カペラの祈り","アルデバランの瞳","冬天のリゲル"],"art":"covers/celestial-diamond.jpg","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"セレスティアル・ダイヤモンド"},{"id":"devouring-eden","artist":"越黒リタ","title":"Devouring Eden","albumNumber":28,"release":"","order":35,"story":[],"tracks":["ネペンテスの蜜牢","セファロタスの湿葬","サラセニアの聖杯","ヘリアンフォラの雨宮","ディオネアの接吻","ドロセラの涙冠"],"art":"covers/devouring-eden.jpg","accent":"crimson","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":"デヴァウリング・エデン"},{"id":"schattenblute","artist":"CROVEIL","title":"Schattenblüte","albumNumber":8,"release":"","order":36,"story":[],"tracks":["蒼の証明","甘い破片","幻の残香","鏡の黒蝶","夜底に咲く","静寂の底"],"art":"data:image/jpeg;base64,","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":""},{"id":"tarnished-beauty","artist":"越黒リタ","title":"Tarnished Beauty","albumNumber":29,"release":"","order":37,"story":[],"tracks":["Sacred Sin","Lost Key","Eternal Rose","Cold Blade","Skull Grace","Silver Heart"],"art":"data:image/jpeg;base64,","accent":"blue","youtubeId":"","links":{"spotify":"https://open.spotify.com/artist/24ZhFNgFRKfS19yAisfM0Q","apple":"https://music.apple.com/jp/artist/%E8%B6%8A%E9%BB%92%E3%83%AA%E3%82%BF/1852020293","amazon":"https://music.amazon.com/artists/B0G48Q368M"},"reading":""}];
